const baseUrl = $('Set Config Fields').item.json.jiraBaseUrl;
const issues = $input.all().map(item => {
  const issue = item.json;
  return {
    key: issue.key,
    summary: issue.fields?.summary,
    status: issue.fields?.status?.name,
    assignee: issue.fields?.assignee?.displayName || 'Unassigned',
    assigneeAccountId: issue.fields?.assignee?.accountId || null,
    updated: issue.fields?.updated,
    url: `${baseUrl}/browse/${issue.key}`
  };
});
return [{ json: { recentIssues: issues } }];

const baseUrl = $('Set Config Fields').item.json.jiraBaseUrl;
const now = Date.now();
const issues = $input.all().map(item => {
  const issue = item.json;
  const updated = new Date(issue.fields?.updated).getTime();
  const daysStale = Math.floor((now - updated) / 86400000);
  return {
    key: issue.key,
    summary: issue.fields?.summary,
    status: issue.fields?.status?.name,
    assignee: issue.fields?.assignee?.displayName || 'Unassigned',
    assigneeAccountId: issue.fields?.assignee?.accountId || null,
    updated: issue.fields?.updated,
    daysStale,
    url: `${baseUrl}/browse/${issue.key}`
  };
});
return [{ json: { staleIssues: issues } }];

const config = $json;
const sinceISO = new Date(Date.now() - 24*60*60*1000).toISOString();
const staleHours = config.staleReviewHours || 48;
const staleDateISO = new Date(Date.now() - staleHours*60*60*1000).toISOString().split('T')[0];
return (config.repos || []).map(repo => ({
  json: {
    owner: repo.owner,
    name: repo.name,
    fullName: `${repo.owner}/${repo.name}`,
    sinceISO,
    staleDateISO
  }
}));

const results = [];
for (const item of $input.all()) {
  const body = item.json;
  if (Array.isArray(body)) {
    for (const pr of body) {
      if (pr && pr.number != null) results.push({ json: pr });
    }
  } else if (body && body.number != null) {
    results.push({ json: body });
  }
}
return results.length ? results : [{ json: { number: null } }];

const results = [];
for (const item of $input.all()) {
  const body = item.json;
  const list = Array.isArray(body?.items) ? body.items : [];
  for (const issue of list) {
    if (issue && issue.number != null) results.push({ json: issue });
  }
}
return results.length ? results : [{ json: { number: null } }];

const now = Date.now();
const cutoff = now - 24*60*60*1000;
const prs = $input.all().map(i => i.json).filter(pr => pr && pr.number != null);
const opened = [], merged = [], closed = [];
for (const pr of prs) {
  const createdAt = new Date(pr.created_at).getTime();
  const mergedAt = pr.merged_at ? new Date(pr.merged_at).getTime() : null;
  const closedAt = pr.closed_at ? new Date(pr.closed_at).getTime() : null;
  const entry = {
    number: pr.number,
    title: pr.title,
    author: pr.user?.login,
    url: pr.html_url,
    repo: pr.base?.repo?.full_name
  };
  if (createdAt >= cutoff) opened.push(entry);
  if (mergedAt && mergedAt >= cutoff) merged.push(entry);
  if (closedAt && !mergedAt && closedAt >= cutoff) closed.push(entry);
}
return [{ json: { prsOpened: opened, prsMerged: merged, prsClosed: closed } }];

const staleReviewHours = $('Set Config Fields').item.json.staleReviewHours || 48;
const cutoffMs = staleReviewHours * 60 * 60 * 1000;
const now = Date.now();
const prs = $input.all().map(i => i.json).filter(pr => pr && pr.number != null);
const stale = prs
  .filter(pr => (now - new Date(pr.created_at).getTime()) > cutoffMs)
  .map(pr => ({
    number: pr.number,
    title: pr.title,
    author: pr.user?.login,
    url: pr.html_url,
    repo: (pr.repository_url || '').split('/repos/')[1],
    hoursOpen: Math.floor((now - new Date(pr.created_at).getTime()) / 3600000)
  }));
return [{ json: { prsAwaitingReview: stale } }];

const response = $json;
const digest = $('Merge Overall Digest').item.json;
let parsed;
try {
  const content = response.choices[0].message.content;
  parsed = JSON.parse(content);
} catch (e) {
  parsed = {
    whatMoved: 'Summary unavailable — the LLM response could not be parsed.',
    whatShipped: '',
    whatIsBlocked: '',
    needsReview: '',
    sprintHealth: 'Unknown — check the digest workflow run for errors.'
  };
}
return [{ json: { summary: parsed, digest } }];

const { summary, digest } = $json;
const userMap = $('Set Config Fields').item.json.userMap || {};

function mention(idOrLogin) {
  const slackId = userMap[idOrLogin];
  return slackId ? `<@${slackId}>` : (idOrLogin || 'unassigned');
}

const staleMentions = (digest.staleIssues || []).map(i => mention(i.assigneeAccountId || i.assignee));
const reviewMentions = (digest.prsAwaitingReview || []).map(p => mention(p.author));
const allMentions = [...new Set([...staleMentions, ...reviewMentions])].filter(m => m.startsWith('<@'));

const blocks = [
  { type: 'header', text: { type: 'plain_text', text: '📋 Engineering Daily Digest' } },
  { type: 'section', text: { type: 'mrkdwn', text: `*Sprint health:* ${summary.sprintHealth}` } },
  { type: 'divider' },
  { type: 'section', text: { type: 'mrkdwn', text: `*What moved*\n${summary.whatMoved}` } },
  { type: 'section', text: { type: 'mrkdwn', text: `*What shipped*\n${summary.whatShipped}` } },
  { type: 'section', text: { type: 'mrkdwn', text: `*What's blocked*\n${summary.whatIsBlocked}` } },
  { type: 'section', text: { type: 'mrkdwn', text: `*Needs review*\n${summary.needsReview}` } },
  { type: 'divider' },
  { type: 'section', text: { type: 'mrkdwn', text: `*Stale tickets (${(digest.staleIssues||[]).length})*\n` + ((digest.staleIssues||[]).map(i => `• <${i.url}|${i.key}> — ${i.summary} (${i.daysStale}d, ${mention(i.assigneeAccountId || i.assignee)})`).join('\n') || '_none_') } },
  { type: 'section', text: { type: 'mrkdwn', text: `*PRs awaiting review (${(digest.prsAwaitingReview||[]).length})*\n` + ((digest.prsAwaitingReview||[]).map(p => `• <${p.url}|#${p.number} ${p.title}> — ${p.hoursOpen}h, ${mention(p.author)}`).join('\n') || '_none_') } }
];

if (allMentions.length) {
  blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: `cc ${allMentions.join(' ')}` }] });
}

return [{ json: { blocks, text: `Engineering Daily Digest — ${summary.sprintHealth}`, digest, summary } }];
